"use client"

import * as React from "react"
import {
  CircleCheckIcon,
  InfoIcon,
  Loader2Icon,
  OctagonXIcon,
  TriangleAlertIcon,
} from "lucide-react"
import { useTheme } from "next-themes"
import { Toaster as Sonner, type ToasterProps } from "sonner"

import { useDirection } from "@/hooks/use-direction"
import { cn } from "@/lib/utils"

/** Keep Sonner theme aligned with `.dark` (same source as design tokens). */
function useDocumentColorScheme(): "light" | "dark" {
  const [scheme, setScheme] = React.useState<"light" | "dark">("light")

  React.useLayoutEffect(() => {
    const root = document.documentElement
    const sync = () =>
      setScheme(root.classList.contains("dark") ? "dark" : "light")
    sync()
    const observer = new MutationObserver(sync)
    observer.observe(root, { attributes: true, attributeFilter: ["class"] })
    return () => observer.disconnect()
  }, [])

  return scheme
}

function Toaster({
  theme: themeProp,
  dir: dirProp,
  toastOptions,
  className,
  style,
  ...props
}: ToasterProps) {
  const { theme: nextTheme, resolvedTheme } = useTheme()
  const documentScheme = useDocumentColorScheme()
  // Portaled under body — prefer explicit dir, else DirectionProvider / <html>.
  const { dir: contextDir } = useDirection()
  const dir = dirProp ?? contextDir

  // Prefer explicit prop → next-themes resolved → `.dark` on <html> (CSS tokens).
  const theme: ToasterProps["theme"] =
    themeProp ??
    (resolvedTheme === "light" || resolvedTheme === "dark"
      ? resolvedTheme
      : nextTheme === "light" || nextTheme === "dark"
        ? nextTheme
        : documentScheme)

  return (
    <Sonner
      theme={theme}
      className={cn("toaster group", className)}
      dir={dir}
      icons={{
        success: <CircleCheckIcon className="size-4" />,
        info: <InfoIcon className="size-4" />,
        warning: <TriangleAlertIcon className="size-4" />,
        error: <OctagonXIcon className="size-4" />,
        loading: <Loader2Icon className="size-4 animate-spin" />,
      }}
      toastOptions={{
        ...toastOptions,
        classNames: {
          ...toastOptions?.classNames,
          // Sonner hardcodes description colors per theme; force design tokens
          // so light/dark never desync from --popover / --muted-foreground.
          description: cn(
            "!text-muted-foreground",
            toastOptions?.classNames?.description
          ),
        },
      }}
      style={
        {
          "--normal-bg": "var(--popover)",
          "--normal-text": "var(--popover-foreground)",
          "--normal-border": "var(--border)",
          "--border-radius": "var(--radius)",
          ...style,
        } as React.CSSProperties
      }
      {...props}
    />
  )
}

export { Toaster }

export type Direction = "ltr" | "rtl"

export const DEFAULT_DIRECTION: Direction = "ltr"

export function isDirection(value: unknown): value is Direction {
  return value === "ltr" || value === "rtl"
}

export function normalizeDirection(
  value: string | null | undefined,
  fallback: Direction = DEFAULT_DIRECTION
): Direction {
  if (value === "rtl" || value === "ltr") return value
  return fallback
}

export function isRtl(dir: Direction) {
  return dir === "rtl"
}

export function getOppositeDirection(dir: Direction): Direction {
  return dir === "rtl" ? "ltr" : "rtl"
}

export function getStartSide(dir: Direction): "left" | "right" {
  return dir === "rtl" ? "right" : "left"
}

export function getEndSide(dir: Direction): "left" | "right" {
  return dir === "rtl" ? "left" : "right"
}

export type EdgeSide = "top" | "bottom" | "left" | "right" | "start" | "end"

export type PhysicalEdgeSide = "top" | "bottom" | "left" | "right"

export function resolveEdgeSide(
  side: EdgeSide | undefined,
  dir: Direction,
  fallback: PhysicalEdgeSide = "bottom"
): PhysicalEdgeSide {
  const value = side ?? fallback
  if (value === "start") return getStartSide(dir)
  if (value === "end") return getEndSide(dir)
  return value
}

export function readElementDirection(
  el?: Element | null,
  fallback: Direction = DEFAULT_DIRECTION
): Direction {
  if (!el || typeof window === "undefined") return fallback
  const raw = getComputedStyle(el).direction
  return normalizeDirection(raw, fallback)
}

"use client"

import * as React from "react"

import {
  DEFAULT_DIRECTION,
  type Direction,
  isRtl,
  normalizeDirection,
  readElementDirection,
} from "@/lib/direction"

const DirectionContext = React.createContext<Direction | null>(null)

export function DirectionContextProvider({
  dir,
  children,
}: {
  dir: Direction
  children: React.ReactNode
}) {
  return (
    <DirectionContext.Provider value={dir}>{children}</DirectionContext.Provider>
  )
}

export function useDirection(): {
  dir: Direction
  isRtl: boolean
} {
  const fromContext = React.useContext(DirectionContext)
  const [inherited, setInherited] = React.useState<Direction>(DEFAULT_DIRECTION)

  React.useLayoutEffect(() => {
    if (fromContext) {
      setInherited(fromContext)
      return
    }
    setInherited(readElementDirection(document.documentElement))
  }, [fromContext])

  const dir = fromContext ?? inherited

  return {
    dir,
    isRtl: isRtl(dir),
  }
}

export function useDocumentDirection(): Direction {
  const [dir, setDir] = React.useState<Direction>(DEFAULT_DIRECTION)

  React.useEffect(() => {
    const root = document.documentElement
    const sync = () =>
      setDir(normalizeDirection(root.getAttribute("dir"), DEFAULT_DIRECTION))
    sync()
    const observer = new MutationObserver(sync)
    observer.observe(root, { attributes: true, attributeFilter: ["dir"] })
    return () => observer.disconnect()
  }, [])

  return dir
}

export { DirectionContext }
